#!/usr/bin/env python3
"""One-shot patch transport. SHA-256 verifies its decompressed, guarded source.
Deleted by its CI job after applying and testing the changes.
"""
import base64
import hashlib
import zlib

PAYLOAD = (
    ""
    ""
    ""
    ""
    ""
    ""
)
SOURCE = zlib.decompress(base64.b64decode(PAYLOAD))
EXPECTED_SHA256 = '6ca88da263c5fd5de4c8612a4cc2036730fb1fd1dd24c85ed129872961ac3443'
if hashlib.sha256(SOURCE).hexdigest() != EXPECTED_SHA256:
    raise RuntimeError('Patch transport failed integrity verification')
exec(compile(SOURCE, '<guarded remaining V3 patch>', 'exec'))
